import { Ionicons } from "@expo/vector-icons";
import { useMutation, useQuery } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { useState } from "react";
import { ActivityIndicator, Pressable, StyleSheet, Text, TextInput, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { createSession } from "../auth/auth.api";
import { firebaseAuth } from "../auth/firebase";
import { useAuthStore } from "../auth/auth.store";
import { getCategories } from "../catalog/catalog.api";
import { registerVendor } from "./vendor.api";

const initial = { legalName: "", displayName: "", phone: "", description: "", line1: "", division: "", district: "", upazila: "", unionName: "" };

export function VendorRegistrationScreen() {
  const router = useRouter();
  const user = firebaseAuth?.currentUser ?? null;
  const session = useAuthStore((state) => state.session);
  const setSession = useAuthStore((state) => state.setSession);
  const categories = useQuery({ queryKey: ["catalog", "categories"], queryFn: getCategories });
  const [form, setForm] = useState(initial);
  const [categoryIds, setCategoryIds] = useState<string[]>([]);
  const [accepted, setAccepted] = useState(false);
  const submit = useMutation({ mutationFn: () => registerVendor(user!, { legalName: form.legalName, displayName: form.displayName, phone: form.phone, description: form.description.trim() || null, address: { line1: form.line1, division: form.division, district: form.district, upazila: form.upazila, unionName: form.unionName.trim() || null }, categoryIds, acceptedTerms: true, termsVersion: "2026.06", privacyVersion: "2026.06" }), onSuccess: async () => { setSession(await createSession(user!)); router.replace("/vendor/settings"); } });
  if (!user) return <Screen title="Become a seller" description="Sign in or create an account before submitting a seller application."><Action label="Sign in" onPress={() => router.push("/auth")} /></Screen>;
  if (session?.vendorMemberships.length) return <Screen title="Seller workspace already connected" description="This account already belongs to a seller workspace."><Action label="Open seller dashboard" onPress={() => router.replace("/vendor/dashboard")} /></Screen>;
  const valid = form.legalName.trim().length >= 3 && form.displayName.trim().length >= 3 && form.phone.trim().length >= 8 && form.line1.trim().length >= 3 && form.division.trim().length >= 2 && form.district.trim().length >= 2 && form.upazila.trim().length >= 2 && categoryIds.length > 0 && accepted;
  return <Screen eyebrow="SELL ON AMIYO-GO" title="Create your seller workspace" description="Submit your business and pickup details. The workspace stays pending until platform review and KYC approval."><ModuleCard title="Business identity" meta="Use information that matches your verification documents."><Field label="Legal business or owner name" value={form.legalName} onChangeText={(legalName) => setForm({ ...form, legalName })} /><Field label="Shop display name" value={form.displayName} onChangeText={(displayName) => setForm({ ...form, displayName })} /><Field keyboardType="phone-pad" label="Business phone" value={form.phone} onChangeText={(phone) => setForm({ ...form, phone })} /><Field label="Shop description (optional)" multiline value={form.description} onChangeText={(description) => setForm({ ...form, description })} /></ModuleCard><ModuleCard title="Pickup address" meta="Used for delivery dispatch after approval."><Field label="Address details" value={form.line1} onChangeText={(line1) => setForm({ ...form, line1 })} /><View style={styles.columns}><View style={styles.flex}><Field label="Division" value={form.division} onChangeText={(division) => setForm({ ...form, division })} /></View><View style={styles.flex}><Field label="District" value={form.district} onChangeText={(district) => setForm({ ...form, district })} /></View></View><View style={styles.columns}><View style={styles.flex}><Field label="Upazila" value={form.upazila} onChangeText={(upazila) => setForm({ ...form, upazila })} /></View><View style={styles.flex}><Field label="Union (optional)" value={form.unionName} onChangeText={(unionName) => setForm({ ...form, unionName })} /></View></View></ModuleCard><ModuleCard title="Product categories" meta="Select the categories you plan to sell in. Each selection enters the admin review queue.">{categories.isLoading ? <ActivityIndicator color={colors.primary} /> : <View style={styles.chips}>{categories.data?.map((category) => { const selected = categoryIds.includes(category.id); return <Pressable key={category.id} onPress={() => setCategoryIds((current) => selected ? current.filter((id) => id !== category.id) : [...current, category.id])} style={[styles.chip, selected && styles.chipActive]}><Ionicons color={selected ? "#fff" : colors.primary} name={selected ? "checkmark-circle" : "ellipse-outline"} size={17} /><Text style={[styles.chipText, selected && styles.chipTextActive]}>{category.name}</Text></Pressable>; })}</View>}{categories.error ? <Text style={styles.error}>Could not load categories.</Text> : null}</ModuleCard><Pressable onPress={() => setAccepted((value) => !value)} style={styles.consent}><Ionicons color={accepted ? colors.primary : colors.muted} name={accepted ? "checkbox" : "square-outline"} size={24} /><Text style={styles.consentText}>I accept the Terms and Conditions and Privacy Policy version 2026.06.</Text></Pressable>{submit.error ? <Text style={styles.error}>{submit.error.message}</Text> : null}<Action busy={submit.isPending} disabled={!valid} label="Submit seller application" onPress={() => submit.mutate()} /><Text style={styles.note}>After submission, add KYC documents and payout information from Seller Settings.</Text></Screen>;
}

function Field(props: React.ComponentProps<typeof TextInput> & { label: string }) { const { label, ...input } = props; return <View style={styles.field}><Text style={styles.label}>{label}</Text><TextInput placeholderTextColor={colors.muted} style={[styles.input, input.multiline && styles.multiline]} {...input} /></View>; }
function Action({ busy, disabled, label, onPress }: { busy?: boolean; disabled?: boolean; label: string; onPress(): void }) { return <Pressable disabled={busy || disabled} onPress={onPress} style={[styles.action, (busy || disabled) && styles.disabled]}>{busy ? <ActivityIndicator color="#fff" /> : <Text style={styles.actionText}>{label}</Text>}</Pressable>; }
const styles = StyleSheet.create({ field: { gap: 5 }, label: { color: colors.text, fontSize: 12, fontWeight: "800" }, input: { backgroundColor: "#f8fafc", borderColor: colors.border, borderRadius: radius.md, borderWidth: 1, color: colors.text, minHeight: 46, paddingHorizontal: 12 }, multiline: { minHeight: 90, paddingVertical: 10, textAlignVertical: "top" }, columns: { flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, flex: { flex: 1, minWidth: 180 }, chips: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, chip: { alignItems: "center", borderColor: colors.border, borderRadius: radius.pill, borderWidth: 1, flexDirection: "row", gap: 6, paddingHorizontal: 12, paddingVertical: 9 }, chipActive: { backgroundColor: colors.primary, borderColor: colors.primary }, chipText: { color: colors.text, fontSize: 12, fontWeight: "800" }, chipTextActive: { color: "#fff" }, consent: { alignItems: "flex-start", backgroundColor: colors.primarySoft, borderRadius: radius.lg, flexDirection: "row", gap: spacing.sm, padding: spacing.md }, consentText: { color: colors.text, flex: 1, lineHeight: 21 }, action: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", minHeight: 50 }, actionText: { color: "#fff", fontWeight: "900" }, disabled: { opacity: .45 }, error: { color: colors.danger }, note: { color: colors.muted, fontSize: 12, textAlign: "center" } });
